package com.olunaa.app;

import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;import androidx.annotation.NonNull;import androidx.appcompat.app.AppCompatActivity;import androidx.biometric.*;import androidx.core.content.ContextCompat;import org.json.*;import java.io.*;import java.net.*;import java.util.concurrent.*;

public class MainActivity extends AppCompatActivity {
 private static final String API="https://olunaa.vercel.app/api"; private static final int BG=Color.rgb(7,9,15),CARD=Color.rgb(17,20,29),CARD2=Color.rgb(25,29,41),TEXT=Color.rgb(246,248,253),MUTED=Color.rgb(151,159,179),ACCENT=Color.rgb(91,92,255),BLUE=Color.rgb(40,145,255);
 private final ExecutorService io=Executors.newCachedThreadPool(); private final Handler handler=new Handler(Looper.getMainLooper()); private final CookieManager cookies=new CookieManager(null,CookiePolicy.ACCEPT_ALL); private LinearLayout root,content; private TextView title; private String meId="",meUsername="",currentConversation="";
 @Override protected void onCreate(Bundle b){super.onCreate(b);CookieHandler.setDefault(cookies);getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE,WindowManager.LayoutParams.FLAG_SECURE);showAuth(false);}
 private TextView tv(String s,float z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);return v;} private GradientDrawable bg(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;} private Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(TEXT);b.setTextSize(14);b.setAllCaps(false);b.setBackground(bg(ACCENT,28));return b;} private EditText input(String h){EditText e=new EditText(this);e.setHint(h);e.setHintTextColor(MUTED);e.setTextColor(TEXT);e.setSingleLine(true);e.setTextSize(15);e.setPadding(18,0,18,0);e.setBackground(bg(CARD2,26));e.setLayoutParams(new LinearLayout.LayoutParams(-1,58));return e;} private void base(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);root.setPadding(16,16,16,10);setContentView(root);}
 private void showAuth(boolean reg){base();LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER_HORIZONTAL);ScrollView sc=new ScrollView(this);sc.addView(box);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));TextView logo=tv("✦",64,ACCENT);box.addView(logo,new LinearLayout.LayoutParams(-2,92));TextView brand=tv("OLUNAA  ✓",32,TEXT);brand.setTypeface(null,1);box.addView(brand);box.addView(tv("Private • Fast • Connected",15,MUTED));Space sp=new Space(this);box.addView(sp,new LinearLayout.LayoutParams(1,24));EditText name=null,email=input("Email address"),user=input("Username or @username"),pass=input("Password");if(reg){name=input("Display name");box.addView(name);box.addView(email);}box.addView(user);box.addView(pass);Button go=btn(reg?"Create account":"Sign in");box.addView(go,new LinearLayout.LayoutParams(-1,58));TextView toggle=tv(reg?"Already have an account?  Sign in":"New to OLUNAA?  Create account",14,ACCENT);toggle.setGravity(Gravity.CENTER);toggle.setPadding(0,22,0,18);box.addView(toggle);TextView forgot=tv("Forgot password?",14,MUTED);forgot.setGravity(Gravity.CENTER);if(!reg)box.addView(forgot);go.setOnClickListener(v->{JSONObject j=new JSONObject();try{if(reg){j.put("displayName",name.getText().toString());j.put("email",email.getText().toString());j.put("username",user.getText().toString());}else j.put("identifier",user.getText().toString());j.put("password",pass.getText().toString());}catch(Exception ignored){}go.setEnabled(false);api(reg?"/auth/register":"/auth/login","POST",j,r->{go.setEnabled(true);if(r.ok){JSONObject u=r.data.optJSONObject("user");if(u==null&&r.data.optJSONObject("data")!=null)u=r.data.optJSONObject("data").optJSONObject("user");if(u!=null){meId=u.optString("id");meUsername=u.optString("username");showHome();}}else toast(r.error);});});toggle.setOnClickListener(v->showAuth(!reg));forgot.setOnClickListener(v->showForgot());}
 private void showForgot(){base();LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);root.addView(b);b.addView(tv("Reset your password",28,TEXT));b.addView(tv("Username or email",14,MUTED));EditText id=input("Username or email");b.addView(id);Button go=btn("Send reset link");b.addView(go,new LinearLayout.LayoutParams(-1,58));go.setOnClickListener(v->{JSONObject j=new JSONObject();try{j.put("identifier",id.getText().toString());}catch(Exception ignored){}api("/auth/forgot","POST",j,r->toast(r.ok?"Reset request sent if the account exists.":r.error));});TextView back=tv("Back to sign in",14,ACCENT);back.setPadding(0,20,0,0);b.addView(back);back.setOnClickListener(v->showAuth(false));}
 private void showHome(){base();LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);TextView mark=tv("✦",32,ACCENT);head.addView(mark,new LinearLayout.LayoutParams(48,58));LinearLayout names=new LinearLayout(this);names.setOrientation(LinearLayout.VERTICAL);title=tv("Chats",24,TEXT);title.setTypeface(null,1);names.addView(title);names.addView(tv("@"+meUsername+"  •  online",13,MUTED));head.addView(names,new LinearLayout.LayoutParams(0,58,1));Button plus=btn("＋");head.addView(plus,new LinearLayout.LayoutParams(58,52));root.addView(head);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);String[] ns={"Chats","Status","Calls","Community","Profile"};for(String n:ns){Button x=btn(n);x.setTextSize(10);x.setBackground(bg(CARD,22));x.setOnClickListener(v->switchTab(n));nav.addView(x,new LinearLayout.LayoutParams(0,54,1));}root.addView(nav);plus.setOnClickListener(v->newChat());loadChats();}
 private void switchTab(String n){title.setText(n);content.removeAllViews();if(n.equals("Chats"))loadChats();else if(n.equals("Status"))loadStatus();else if(n.equals("Calls"))loadCalls();else if(n.equals("Community"))loadCommunity();else loadProfile();}
 private void loadChats(){content.addView(tv("Messages",14,MUTED));api("/conversations","GET",null,r->{if(!r.ok){content.addView(tv(r.error,16,TEXT));return;}JSONArray a=r.data.optJSONArray("conversations");if(a==null||a.length()==0){content.addView(tv("No chats yet. Tap ＋ to find someone.",17,TEXT));return;}for(int i=0;i<a.length();i++){JSONObject c=a.optJSONObject(i),o=c.optJSONObject("other");if(o==null)continue;JSONObject lm=c.optJSONObject("lastMessage");String last=lm==null?"":lm.optString("body","");String verified=o.optBoolean("verified")?"  ✓":"";TextView row=tv((o.optBoolean("online")?"● ":"○ ")+o.optString("displayName")+verified+"\n@"+o.optString("username")+(last.isEmpty()?"":"   "+last),16,TEXT);row.setPadding(18,14,18,14);row.setBackground(bg(CARD,22));content.addView(row,new LinearLayout.LayoutParams(-1,82));String cid=c.optString("id");row.setOnClickListener(v->openChat(cid,o.optString("displayName")));}});}
 private void openChat(String cid,String name){currentConversation=cid;content.removeAllViews();LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView back=tv("‹",36,TEXT);bar.addView(back,new LinearLayout.LayoutParams(45,55));TextView h=tv(name+"  ✓",20,TEXT);h.setTypeface(null,1);bar.addView(h,new LinearLayout.LayoutParams(0,55,1));Button call=btn("☎"),video=btn("▣");bar.addView(call,new LinearLayout.LayoutParams(54,50));bar.addView(video,new LinearLayout.LayoutParams(64,50));content.addView(bar);back.setOnClickListener(v->{currentConversation="";loadChats();});call.setOnClickListener(v->toast("Voice call UI is ready; live WebRTC signaling server is still required."));video.setOnClickListener(v->toast("Video call UI is ready; live WebRTC signaling server is still required."));ScrollView sc=new ScrollView(this);LinearLayout msgs=new LinearLayout(this);msgs.setOrientation(LinearLayout.VERTICAL);sc.addView(msgs);content.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout send=new LinearLayout(this);Button emoji=btn("☺"),attach=btn("＋");send.addView(attach,new LinearLayout.LayoutParams(48,58));send.addView(emoji,new LinearLayout.LayoutParams(48,58));EditText e=input("Message");send.addView(e,new LinearLayout.LayoutParams(0,58,1));Button s=btn("Send");send.addView(s,new LinearLayout.LayoutParams(76,58));content.addView(send);emoji.setOnClickListener(v->e.append(" 😊"));attach.setOnClickListener(v->toast("Attachment picker will support photos, videos, files and voice notes."));Runnable refresh=()->api("/messages?conversationId="+cid,"GET",null,r->{msgs.removeAllViews();if(!r.ok)return;JSONArray a=r.data.optJSONArray("messages");if(a!=null)for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);boolean mine=meId.equals(m.optString("senderId"));TextView t=tv(m.optString("body")+((mine&&m.optString("seenAt").length()>0)?"  ✓✓":"  ✓"),16,TEXT);t.setPadding(16,12,16,12);t.setBackground(bg(mine?ACCENT:CARD,22));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.gravity=mine?Gravity.RIGHT:Gravity.LEFT;p.setMargins(0,4,0,4);msgs.addView(t,p);}sc.post(()->sc.fullScroll(View.FOCUS_DOWN));});refresh.run();handler.postDelayed(()->{if(currentConversation.equals(cid))refresh.run();},2500);s.setOnClickListener(v->{String text=e.getText().toString().trim();if(text.isEmpty())return;JSONObject j=new JSONObject();try{j.put("conversationId",cid);j.put("body",text);}catch(Exception ignored){}e.setText("");api("/messages","POST",j,r->{if(!r.ok)toast(r.error);else refresh.run();});});}
 private void loadStatus(){content.addView(tv("Status",28,TEXT));content.addView(tv("24-hour updates • viewers are recorded",15,MUTED));Button add=btn("＋ Post status");content.addView(add,new LinearLayout.LayoutParams(-1,58));add.setOnClickListener(v->statusComposer());api("/status","GET",null,r->{if(!r.ok)return;JSONArray a=r.data.optJSONArray("stories");if(a==null)return;for(int i=0;i<a.length();i++){JSONObject st=a.optJSONObject(i),u=st.optJSONObject("user");TextView x=tv("◉  "+(u==null?"User":u.optString("displayName"))+"\n"+st.optString("caption","")+"\n"+st.optJSONArray("views").length()+" views",16,TEXT);x.setPadding(18,15,18,15);x.setBackground(bg(CARD,22));content.addView(x,new LinearLayout.LayoutParams(-1,90));x.setOnClickListener(v->viewStatus(st.optString("id")));}});}
 private void statusComposer(){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);EditText url=input("Photo/video URL");EditText cap=input("Caption");b.addView(url);b.addView(cap);new AlertDialog.Builder(this).setTitle("New status").setView(b).setPositiveButton("Post",(d,w)->{JSONObject j=new JSONObject();try{j.put("mediaUrl",url.getText().toString());j.put("caption",cap.getText().toString());}catch(Exception ignored){}api("/status","POST",j,r->toast(r.ok?"Status posted":"Failed: "+r.error));}).setNegativeButton("Cancel",null).show();}
 private void viewStatus(String id){JSONObject j=new JSONObject();try{j.put("storyId",id);}catch(Exception ignored){}api("/status","PUT",j,r->toast(r.ok?"Status viewed • "+r.data.optInt("views")+" viewers":"Unable to view status"));}
 private void loadCommunity(){content.addView(tv("OLUNAA Community",28,TEXT));content.addView(tv("Official announcements and public channels",15,MUTED));api("/channels","GET",null,r->{if(!r.ok){content.addView(tv(r.error,15,TEXT));return;}JSONArray a=r.data.optJSONArray("channels");if(a==null||a.length()==0){content.addView(tv("No channels yet.",16,TEXT));return;}for(int i=0;i<a.length();i++){JSONObject c=a.optJSONObject(i);Button b=btn("✦  "+c.optString("name")+"  ✓\n@"+c.optString("handle"));b.setTextSize(14);b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);content.addView(b,new LinearLayout.LayoutParams(-1,70));b.setOnClickListener(v->openChannel(c.optString("handle")));}});}
 private void openChannel(String handle){content.removeAllViews();content.addView(tv("Official Channel  ✓",24,TEXT));api("/channels?handle="+handle,"GET",null,r->{if(!r.ok)return;JSONObject c=r.data.optJSONObject("channel");content.addView(tv(c.optString("name")+"  ✓\n@"+c.optString("handle")+"\n"+c.optString("description","")+"\n\nADMIN POSTS",16,TEXT));JSONArray a=c.optJSONArray("messages");if(a!=null)for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i),u=m.optJSONObject("author");TextView x=tv((u==null?"Admin":u.optString("displayName"))+"  ✓\n"+m.optString("body"),16,TEXT);x.setPadding(18,14,18,14);x.setBackground(bg(CARD,22));content.addView(x,new LinearLayout.LayoutParams(-1,90));}});}
 private void loadCalls(){content.addView(tv("Calls",28,TEXT));content.addView(tv("Voice and video",16,MUTED));content.addView(tv("No recent calls",17,TEXT));}
 private void loadProfile(){api("/profile","GET",null,r->{if(!r.ok){content.addView(tv(r.error,16,TEXT));return;}JSONObject u=r.data.optJSONObject("user");content.addView(tv("✦  "+u.optString("displayName")+(u.optBoolean("verified")?"  ✓":""),28,TEXT));content.addView(tv("@"+u.optString("username")+"\n\n"+u.optString("bio","Add a bio to tell people about you."),16,MUTED));Button edit=btn("Edit profile");content.addView(edit,new LinearLayout.LayoutParams(-1,58));edit.setOnClickListener(v->editProfile(u));Button lock=btn("Fingerprint / device lock");content.addView(lock,new LinearLayout.LayoutParams(-1,58));lock.setOnClickListener(v->biometric());Button out=btn("Sign out");content.addView(out,new LinearLayout.LayoutParams(-1,58));out.setOnClickListener(v->api("/auth/logout","POST",null,r2->showAuth(false)));});}
 private void editProfile(JSONObject u){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);EditText n=input("Display name");n.setText(u.optString("displayName"));EditText bio=input("Bio");bio.setText(u.optString("bio"));EditText av=input("Avatar image URL");av.setText(u.optString("avatarUrl"));b.addView(n);b.addView(bio);b.addView(av);new AlertDialog.Builder(this).setTitle("Edit profile").setView(b).setPositiveButton("Save",(d,w)->{JSONObject j=new JSONObject();try{j.put("displayName",n.getText().toString());j.put("bio",bio.getText().toString());j.put("avatarUrl",av.getText().toString());}catch(Exception ignored){}api("/profile","PATCH",j,r->toast(r.ok?"Profile updated":"Update failed: "+r.error));}).setNegativeButton("Cancel",null).show();}
 private void biometric(){if(BiometricManager.from(this).canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_STRONG|BiometricManager.Authenticators.DEVICE_CREDENTIAL)!=BiometricManager.BIOMETRIC_SUCCESS){toast("Set a fingerprint, face or device PIN first.");return;}BiometricPrompt p=new BiometricPrompt(this,ContextCompat.getMainExecutor(this),new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(@NonNull BiometricPrompt.AuthenticationResult r){getPreferences(0).edit().putBoolean("lock",true).apply();toast("Biometric lock enabled");}});p.authenticate(new BiometricPrompt.PromptInfo.Builder().setTitle("Unlock OLUNAA").setSubtitle("Protect this app").setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG|BiometricManager.Authenticators.DEVICE_CREDENTIAL).build());}
 private void newChat(){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);EditText q=input("Username, e.g. @anas");b.addView(q);new AlertDialog.Builder(this).setTitle("Start a new chat").setView(b).setPositiveButton("Find",(d,w)->{content.removeAllViews();title.setText("Discover");loadDiscover(q.getText().toString());}).setNegativeButton("Cancel",null).show();}
 private void loadDiscover(String initial){content.addView(tv("Discover",28,TEXT));EditText q=input("Search @username or name");q.setText(initial);content.addView(q);Button b=btn("Search");content.addView(b,new LinearLayout.LayoutParams(-1,56));TextView out=tv("Find people and start a conversation.",15,MUTED);content.addView(out);b.setOnClickListener(v->api("/search?q="+q.getText().toString().trim(),"GET",null,r->out.setText(r.ok?r.data.toString():r.error)));}
 private void api(String path,String method,JSONObject body,java.util.function.Consumer<Result> cb){io.execute(()->{Result out=new Result();try{HttpURLConnection c=(HttpURLConnection)new URL(API+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setRequestProperty("Accept","application/json");if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream os=c.getOutputStream()){os.write(body.toString().getBytes("UTF-8"));}}int code=c.getResponseCode();InputStream is=code>=400?c.getErrorStream():c.getInputStream();String text=read(is);out.code=code;out.ok=code>=200&&code<300;out.data=new JSONObject(text);out.error=out.data.optString("error","");}catch(Exception e){out.ok=false;out.error=e.getMessage()==null?"Network error":e.getMessage();}runOnUiThread(()->cb.accept(out));});}
 private String read(InputStream in)throws Exception{if(in==null)return"{}";BufferedReader r=new BufferedReader(new InputStreamReader(in));StringBuilder s=new StringBuilder();String l;while((l=r.readLine())!=null)s.append(l);return s.toString();}private static class Result{boolean ok;int code;String error="";JSONObject data=new JSONObject();}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}@Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}
}
